use ed25519_dalek::{SigningKey,pkcs8::DecodePrivateKey};
use peerwork_core::{canonical::Path,wire_json::{canonical_wire_json,parse_wire_json_bounded},replayed_secure_journal::{replay_secure_journal_exact,JournalReplayInput},secure_keyring::SecretKeyring,prepared_private_install::{prepare_private_direct_install_begin_with_options,verify_saved_private_direct_install_begin_with_options}};
fn wire(v:&serde_json::Value)->Vec<u8>{canonical_wire_json(&serde_json::to_vec(v).unwrap(),Path::SecureArtifact).unwrap().into_bytes()}
fn main(){
 let args:Vec<_>=std::env::args().collect();let dir=std::path::Path::new(&args[1]);
 let state:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("source/agent.state")).unwrap()).unwrap();
 let item:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("host-fixture.json")).unwrap()).unwrap();let i=&item["sources"][0];let ws=i["workspace_id"].as_str().unwrap();let w=&state["workspaces"][ws];let cp=&w["checkpoint"];
 let commits:Vec<serde_json::Value>=serde_json::from_slice(&std::fs::read(&args[2]).unwrap()).unwrap();let cs:Vec<_>=commits.iter().map(wire).collect();let cr:Vec<_>=cs.iter().map(Vec::as_slice).collect();let ps:Vec<_>=w["policies"].as_array().unwrap().iter().map(wire).collect();let pr:Vec<_>=ps.iter().map(Vec::as_slice).collect();let cpw=wire(cp);let rw=wire(&w["keyring"]);
 let replay=replay_secure_journal_exact(JournalReplayInput{policy_wires:&pr,commit_wires:&cr,checkpoint_wire:&cpw,workspace_id:ws,owner_actor_id:i["owner_actor_id"].as_str().unwrap(),owner_signing_key:i["owner_key_id"].as_str().unwrap(),final_sequence:cp["sequence"].as_u64().unwrap(),final_head:cp["head"].as_str(),final_policy_hash:cp["policy_hash"].as_str().unwrap(),keyring_wire:Some(&rw)}).expect("prior replay");println!("PRIOR_REPLAY_OK");
 let cmd=i["pending_command_id"].as_str().unwrap();let req=wire(&state["pending"][cmd]["body"]);let payload=&state["pending"][cmd]["body"]["commit"]["payload"];
 let material:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("source/install-material.json")).unwrap()).unwrap();let options:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("source/install-options.json")).unwrap()).unwrap();
 let closure=wire(&material["closure"]);let bindings=wire(&material["bindings"]);let grants=wire(&options["grants"]);let policy=ps.last().unwrap();let key=SigningKey::from_pkcs8_pem(&std::fs::read_to_string(dir.join("source/owner.pem")).unwrap()).unwrap();let ring=SecretKeyring::parse_wire(&rw).unwrap();let epoch=payload["epoch"].as_u64().unwrap();let ek=ring.key_at(epoch).unwrap();
 let root=material["closure"]["root_package_digest"].as_str().unwrap();let digest=i["protocol_digest"].as_str().unwrap();let inst=i["instance_id"].as_str().unwrap();let entry=options["entrypoint"].as_str().unwrap();let at=payload["issued_at"].as_u64().unwrap();
 let fresh=prepare_private_direct_install_begin_with_options(&closure,&bindings,root,digest,&cpw,policy,replay.objects(),&grants,b"[]",inst,entry,cmd,at,&key,ek).expect("prepare exact");println!("PREPARE_EXACT_OK");
 let v=verify_saved_private_direct_install_begin_with_options(&req,&closure,&bindings,root,digest,&cpw,policy,replay.objects(),&grants,b"[]",inst,entry,cmd,at,&key,ek);println!("SAVED_VERIFY {}",v.is_ok());
 let f:serde_json::Value=serde_json::from_slice(fresh.request_wire()).unwrap();let s:serde_json::Value=serde_json::from_slice(&req).unwrap();println!("POLICY_EQUAL {}",wire(&f["policy_update"])==wire(&s["policy_update"]));let mut fp=f["commit"]["payload"].clone();let mut sp=s["commit"]["payload"].clone();for x in [&mut fp,&mut sp]{x.as_object_mut().unwrap().remove("body");x.as_object_mut().unwrap().remove("mode");}println!("CONTEXT_EQUAL {}",wire(&fp)==wire(&sp));
 fn differences(a:&serde_json::Value,b:&serde_json::Value,path:&str,out:&mut Vec<String>){if a==b{return;}if let (Some(a),Some(b))=(a.as_object(),b.as_object()){let keys:std::collections::BTreeSet<_>=a.keys().chain(b.keys()).collect();for k in keys{differences(a.get(k).unwrap_or(&serde_json::Value::Null),b.get(k).unwrap_or(&serde_json::Value::Null),&format!("{path}.{k}"),out);}}else if let (Some(a),Some(b))=(a.as_array(),b.as_array()){if a.len()!=b.len(){out.push(format!("{path}.length"));}else{for (n,(a,b)) in a.iter().zip(b).enumerate(){differences(a,b,&format!("{path}[{n}]"),out);}}}else{out.push(path.to_string());}}
 let mut diffs=vec![];differences(&f["policy_update"]["payload"],&s["policy_update"]["payload"],"policy",&mut diffs);println!("POLICY_DIFF_PATHS {:?}",diffs);let mut diffs=vec![];differences(&fp,&sp,"context",&mut diffs);println!("CONTEXT_DIFF_PATHS {:?}",diffs);
 let fd=&f["policy_update"]["payload"]["structure"]["disclosure"];let sd=&s["policy_update"]["payload"]["structure"]["disclosure"];let sorted=|v:&serde_json::Value|{let mut x=v.as_array().unwrap().iter().map(wire).collect::<Vec<_>>();x.sort();x};println!("DISCLOSURE_MULTISET_EQUAL {}",sorted(fd)==sorted(sd));println!("FRESH_DISCLOSURE_SCHEMA_ORDER {:?}",fd.as_array().unwrap().iter().map(|r|r["schema"].as_str().unwrap()).collect::<Vec<_>>());println!("SAVED_DISCLOSURE_SCHEMA_ORDER {:?}",sd.as_array().unwrap().iter().map(|r|r["schema"].as_str().unwrap()).collect::<Vec<_>>());
 let proof=wire(&serde_json::from_slice::<serde_json::Value>(&std::fs::read(&args[3]).unwrap()).unwrap()["flat"]["composition"]);println!("COMPOSITION_EQUAL {}",fresh.direct_composition().is_some_and(|x|peerwork_core::wire_json::canonical_wire_value(x,Path::SecureArtifact).unwrap().as_bytes()==proof));
}
